"""子状态 checker 模板 — 声明式「识别 → 动作 → 验证」。

批次 4.1 第二阶段的统一入口模板。页面控制器只需声明目标
``(page, substate) + checker``，由 :class:`SubstateSpec` 复用现有的
:func:`~autowsgr.ui.utils.navigation.act_and_wait` /
:func:`~autowsgr.ui.utils.navigation.click_and_wait_for_page` 完成点击、重试、
停止检查和超时分级，成功后自动写入 :class:`~autowsgr.ui.stack.UIStack`。

设计约束
--------
1. **探针不可用时降级**：给出 ``probe`` 时先判断当前画面是否具备验证条件；
   不具备则只执行一次动作 + warning，不记录子状态，也不把「无法验证」
   伪装成「验证失败」。
2. **动作可重试但需幂等**：``click``/``apply`` 默认按 ``retries`` 重试；
   切换类入口可传 ``retries=1``，避免「第一次已生效、第二次又点回去」。
3. **失败统一分级**：等待超时统一包装为 ``PageDriftError``（可恢复级），
   保留页面/动作轨迹，便于上层重试或清弹窗。
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import TYPE_CHECKING

from autowsgr.infra.exceptions import NavigationError, PageDriftError
from autowsgr.infra.logger import get_logger
from autowsgr.ui.stack import record_page_substate
from autowsgr.ui.utils.navigation import (
    NavConfig,
    act_and_wait,
    click_and_wait_for_page,
    wait_for_page,
)


if TYPE_CHECKING:
    from collections.abc import Callable

    import numpy as np

    from autowsgr.context import GameContext
    from autowsgr.vision import PageMatch


_log = get_logger('ui')


@dataclass(frozen=True, slots=True)
class SubstateSpec:
    """一个可验证的子状态目标。

    Parameters
    ----------
    page:
        目标页面名（注册中心里的纯字符串，如 ``PageName.MAP.value``）。
    substate:
        页面内部子状态名（如 ``出征/2-3``、``快速补给``）。
    checker:
        判定是否到达目标子状态的函数。可返回 ``bool`` 或
        :class:`~autowsgr.vision.PageMatch`（后者按 ``matched`` 取真值）。
    timeout:
        每轮验证超时（秒）。
    retries:
        最多尝试次数（含首次）。切换类入口建议 ``1``。
    interval:
        验证轮询间隔（秒）。
    stable_frames:
        判定到达所需的连续匹配帧数；默认 2，挡转场假到达。
    retry_delay:
        两次尝试之间的等待（秒）。
    probe:
        可选探针可用性判断。返回 ``False`` 时只执行一次动作 + warning，
        不重试、不记录子状态。用于「选中态像素点缺失」这类降级场景。
    """

    page: str
    substate: str
    checker: Callable[[np.ndarray], bool | PageMatch]
    timeout: float = 3.0
    retries: int = 2
    interval: float = 0.35
    stable_frames: int = 2
    retry_delay: float = 0.4
    probe: Callable[[np.ndarray], bool] | None = None

    @property
    def target(self) -> str:
        """日志/异常里的目标描述：``页面/子状态``。"""
        return f'{self.page}/{self.substate}'

    def nav_config(self) -> NavConfig:
        """转换为导航原语使用的配置。"""
        return NavConfig(
            max_retries=max(1, self.retries),
            retry_delay=self.retry_delay,
            timeout=self.timeout,
            interval=self.interval,
            stable_frames=max(1, self.stable_frames),
        )

    def _probe_available(self, screen: np.ndarray) -> bool:
        if self.probe is None:
            return True
        return bool(self.probe(screen))

    def _warn_unverified(self, source: str) -> None:
        _log.warning(
            '[UI] 子状态探针不可用, 本次动作不验证: {} -> {}',
            source or self.page,
            self.target,
        )

    def _drift(
        self,
        ctx: GameContext,
        *,
        source: str,
        action_name: str,
    ) -> PageDriftError:
        return PageDriftError(
            f'子状态未到达: {source or self.page} -> {self.target}',
            target=self.target,
            page_trail=[source or self.page, self.target],
            action_trail=[f'{action_name}({self.target})'],
            screen=ctx.ctrl.screenshot(),
        )

    def click(
        self,
        ctx: GameContext,
        click_coord: tuple[float, float],
        *,
        source: str = '',
        action_name: str = 'click',
    ) -> np.ndarray:
        """点击坐标并验证到达目标子状态。

        探针不可用时只点击一次并 warning；否则走
        :func:`click_and_wait_for_page` 的「点击 + 连续帧验证 + 重试」。
        """
        screen = ctx.ctrl.screenshot()
        if not self._probe_available(screen):
            self._warn_unverified(source)
            ctx.ctrl.click(*click_coord)
            return ctx.ctrl.screenshot()

        try:
            result = click_and_wait_for_page(
                ctx.ctrl,
                click_coord,
                self.checker,
                source=source or self.page,
                target=self.target,
                config=self.nav_config(),
                stop_event=ctx.stop_event,
            )
        except NavigationError as exc:
            raise self._drift(ctx, source=source, action_name=action_name) from exc

        record_page_substate(ctx, self.page, self.substate)
        return result

    def apply(
        self,
        ctx: GameContext,
        action: Callable[[], None],
        *,
        source: str = '',
        action_name: str = 'action',
    ) -> np.ndarray:
        """执行任意动作并验证到达目标子状态。

        适用于「多个点击组成一个动作」或「滑动/OCR 后点击」等不便用单坐标
        表达的场景；内部复用 :func:`act_and_wait`。
        """
        screen = ctx.ctrl.screenshot()
        if not self._probe_available(screen):
            self._warn_unverified(source)
            action()
            return ctx.ctrl.screenshot()

        try:
            result = act_and_wait(
                ctx.ctrl,
                action,
                self.checker,
                source=source or self.page,
                target=self.target,
                config=self.nav_config(),
                stop_event=ctx.stop_event,
            )
        except NavigationError as exc:
            raise self._drift(ctx, source=source, action_name=action_name) from exc

        record_page_substate(ctx, self.page, self.substate)
        return result

    def wait(self, ctx: GameContext, *, source: str = '') -> np.ndarray:
        """不执行动作，只验证并登记当前子状态。

        用于「动作已经由其他方法完成，只剩到达确认」的场景，避免重复点击。
        """
        screen = ctx.ctrl.screenshot()
        if not self._probe_available(screen):
            self._warn_unverified(source)
            return screen

        try:
            result = wait_for_page(
                ctx.ctrl,
                self.checker,
                timeout=self.timeout,
                interval=self.interval,
                stable_frames=max(1, self.stable_frames),
                source=source or self.page,
                target=self.target,
                stop_event=ctx.stop_event,
            )
        except NavigationError as exc:
            raise self._drift(ctx, source=source, action_name='wait') from exc

        record_page_substate(ctx, self.page, self.substate)
        return result


__all__ = ['SubstateSpec']
